cat > "$(node -p 'require("os").tmpdir()')/probe-outline.mjs" <<'EOF'
const list = await (await fetch("http://127.0.0.1:9335/json/list")).json();
const page = list.find((t) => t.url.startsWith("app://local"));
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
const expr = `(() => {
  const dot = document.querySelector("button[aria-label='Change color of Read later']");
  const name = dot.parentElement.querySelector('button[aria-pressed]');
  const out = {};
  for (const [k, b] of [['dot', dot], ['name', name]]) {
    b.focus();
    const cs = getComputedStyle(b);
    out[k] = { focusVisible: b.matches(':focus-visible'), active: document.activeElement === b, style: cs.outlineStyle, width: cs.outlineWidth, offset: cs.outlineOffset };
  }
  return JSON.stringify(out);
})()`;
ws.send(JSON.stringify({ id: 1, method: "Runtime.evaluate", params: { expression: expr, returnByValue: true } }));
ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id === 1) { console.log(m.result.result.value ?? JSON.stringify(m.result)); ws.close(); } };
EOF
node "$(node -p 'require("os").tmpdir()')/probe-outline.mjs"

cat > "$(node -p 'require("os").tmpdir()')/probe2.mjs" <<'EOF'
const list = await (await fetch("http://127.0.0.1:9335/json/list")).json();
const page = list.find((t) => t.url.startsWith("app://local"));
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
const expr = `(() => {
  document.querySelectorAll('#pre-fix-sim').forEach((n) => n.remove());
  const s = document.createElement('style'); s.id = 'pre-fix-sim';
  s.textContent = 'button:focus-visible:focus-visible:focus-visible{outline:2px solid red!important;outline-offset:3px!important}';
  document.head.append(s);
  const b = document.querySelector("button[aria-label='Change color of Read later']").parentElement.querySelector('button[aria-pressed]');
  b.focus();
  const cs = getComputedStyle(b);
  return JSON.stringify({ fv: b.matches(':focus-visible'), active: document.activeElement === b, style: cs.outlineStyle, color: cs.outlineColor, sheetRules: s.sheet.cssRules.length, text: b.textContent, cls: b.className.slice(0,200) });
})()`;
ws.send(JSON.stringify({ id: 1, method: "Runtime.evaluate", params: { expression: expr, returnByValue: true } }));
ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id === 1) { console.log(m.result.result?.value ?? JSON.stringify(m.result)); ws.close(); } };
EOF
node "$(node -p 'require("os").tmpdir()')/probe2.mjs"

